import requests, urllib.parse, json
smiles='CN(C)Cc1cc(C(=O)C=Cc2ccc(Cl)c(Cl)c2)cc(CN(C)C)c1O'
key='RRHGMVUZICVUKN-UHFFFAOYSA-N'
urls={
'pubchem_smiles':f'https://pubchem.ncbi.nlm.nih.gov/rest/pug/compound/smiles/{urllib.parse.quote(smiles,safe="")}/property/IUPACName,CanonicalSMILES,IsomericSMILES,InChIKey/JSON',
'pubchem_key':f'https://pubchem.ncbi.nlm.nih.gov/rest/pug/compound/inchikey/{key}/property/IUPACName,CanonicalSMILES,InChIKey/JSON',
'chembl_key':f'https://www.ebi.ac.uk/chembl/api/data/molecule.json?molecule_structures__standard_inchi_key={key}&limit=20',
'chembl_search':f'https://www.ebi.ac.uk/chembl/api/data/molecule.json?q={urllib.parse.quote(smiles)}&limit=20'}
for n,u in urls.items():
 try:
  r=requests.get(u,timeout=20,headers={'Accept':'application/json'})
  print('\n###',n,r.status_code)
  print(r.text[:4000])
 except Exception as e: print(n,e)
